import { useState, useRef, useEffect } from 'react';
import { useMutation } from '@tanstack/react-query';
import { aiApi } from '@/api/ai';
import type { AICandidate, AdvancedGenerateResponse } from '@/api/ai';
import { useGenerationProgress } from '@/hooks/useGenerationProgress';
import { GenerationProgressPanel } from './GenerationProgressPanel';
import { Card, Input, Button, Slider, Badge, Tabs, TabsList, TabsTrigger, TabsContent } from '@/components/ui';
import { Sparkles, Sliders, Tag, Shield, Cherry, AlertTriangle, CheckCircle, X } from 'lucide-react';

const EFFECT_OPTIONS = ['降血压', '抗氧化', '降血糖', '补气养阴', '抗疲劳', '改善睡眠', '增强免疫'];

const INGREDIENT_TYPE_OPTIONS = ['药食同源', '活性肽'];

const TASTE_OPTIONS = ['甜', '苦', '涩', '鲜'];

const SAFETY_LEVEL_OPTIONS = ['常规', '孕妇可用', '儿童可用', '老年适用'];

interface Constraints {
  maxIngredients?: number;
  excludedIngredients?: string[];
  ingredientTypes?: string[];
  tastePreferences?: string[];
  safetyLevel?: string;
}

interface AdvancedGeneratePanelProps {
  onCandidatesGenerated?: (candidates: AICandidate[]) => void;
  className?: string;
}

export function AdvancedGeneratePanel({ onCandidatesGenerated, className }: AdvancedGeneratePanelProps) {
  const [inputMode, setInputMode] = useState<'direct' | 'tag'>('tag');
  const [directInput, setDirectInput] = useState('');
  const [selectedEffects, setSelectedEffects] = useState<string[]>([]);
  const [selectedIngredientTypes, setSelectedIngredientTypes] = useState<string[]>([]);
  const [selectedTastes, setSelectedTastes] = useState<string[]>([]);
  const [selectedSafetyLevel, setSelectedSafetyLevel] = useState<string>('');
  const [excludedIngredients, setExcludedIngredients] = useState<string[]>([]);
  const [excludedInput, setExcludedInput] = useState('');
  const [maxIngredients, setMaxIngredients] = useState(10);
  const [candidates, setCandidates] = useState<AICandidate[] | null>(null);
  const [data, setData] = useState<AdvancedGenerateResponse | null>(null);
  const [priorityValues, setPriorityValues] = useState<Record<string, number>>({
    synergy: 0.7,
    taste: 0.5,
    stability: 0.6,
    safety: 0.8,
  });

  const { progress, startProgress, updateProgress, completeProgress, errorProgress, resetProgress } =
    useGenerationProgress();
  const [announcement, setAnnouncement] = useState('');
  const generateButtonRef = useRef<HTMLButtonElement>(null);

  const mutation = useMutation({
    mutationFn: async () => {
      startProgress('正在准备生成参数...');

      const targetEffects =
        inputMode === 'direct'
          ? directInput
              .split(/[,，]/)
              .map((s) => s.trim())
              .filter(Boolean)
          : selectedEffects;

      const constraints: Constraints = {
        maxIngredients,
        excludedIngredients: excludedIngredients.length > 0 ? excludedIngredients : undefined,
        ingredientTypes: selectedIngredientTypes.length > 0 ? selectedIngredientTypes : undefined,
        tastePreferences: selectedTastes.length > 0 ? selectedTastes : undefined,
        safetyLevel: selectedSafetyLevel || undefined,
      };

      updateProgress('generating', 30, '遗传算法正在生成配方方案...', 15);

      const result = await aiApi.generateAdvanced(targetEffects, priorityValues, constraints, 5);

      updateProgress('optimizing', 60, '正在优化配方参数...', 10);

      updateProgress('validating', 80, '正在进行安全性验证...', 5);

      return result;
    },
    onSuccess: (data) => {
      completeProgress();
      setCandidates(data.candidates);
      setData(data);
      onCandidatesGenerated?.(data.candidates);
    },
    onError: (error) => {
      const errorMessage =
        error instanceof Error && typeof error.message === 'string' ? error.message : '配方生成失败，请稍后重试';
      errorProgress(errorMessage);
    },
  });

  useEffect(() => {
    if (mutation.isPending) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setAnnouncement('开始生成配方，请稍候...');
    }
  }, [mutation.isPending]);

  useEffect(() => {
    if (mutation.isSuccess) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setAnnouncement('配方生成成功');
    } else if (mutation.isError) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setAnnouncement('配方生成失败，请检查输入后重试');
    }
  }, [mutation.isSuccess, mutation.isError]);

  const toggleEffect = (effect: string) => {
    setSelectedEffects((prev) => (prev.includes(effect) ? prev.filter((e) => e !== effect) : [...prev, effect]));
  };

  const handleEffectKeyDown = (e: React.KeyboardEvent, effect: string) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      toggleEffect(effect);
    }
  };

  const handleIngredientTypeKeyDown = (e: React.KeyboardEvent, type: string) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      toggleIngredientType(type);
    }
  };

  const handleTasteKeyDown = (e: React.KeyboardEvent, taste: string) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      toggleTaste(taste);
    }
  };

  const handleSafetyLevelKeyDown = (e: React.KeyboardEvent, level: string) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      setSelectedSafetyLevel(level === selectedSafetyLevel ? '' : level);
    }
  };

  const toggleIngredientType = (type: string) => {
    setSelectedIngredientTypes((prev) => (prev.includes(type) ? prev.filter((t) => t !== type) : [...prev, type]));
  };

  const toggleTaste = (taste: string) => {
    setSelectedTastes((prev) => (prev.includes(taste) ? prev.filter((t) => t !== taste) : [...prev, taste]));
  };

  const addExcludedIngredient = () => {
    const items = excludedInput
      .split(/[,，]/)
      .map((s) => s.trim())
      .filter(Boolean);
    if (items.length > 0) {
      setExcludedIngredients((prev) => [...new Set([...prev, ...items])]);
      setExcludedInput('');
    }
  };

  const removeExcludedIngredient = (item: string) => {
    setExcludedIngredients((prev) => prev.filter((i) => i !== item));
  };

  const handlePriorityChange = (key: string, value: number) => {
    setPriorityValues((prev) => ({ ...prev, [key]: value }));
  };

  const handleCancel = () => {
    mutation.reset();
    resetProgress();
  };

  const canGenerate = inputMode === 'direct' ? directInput.trim().length > 0 : selectedEffects.length > 0;

  return (
    <Card className={`p-6 ${className}`}>
      <span className="sr-only" id="neural-panel-description">
        高级配方优化面板，基于遗传算法多目标优化智能生成配方方案
      </span>
      <div aria-live="polite" className="sr-only">
        {announcement}
      </div>
      <div className="flex items-center gap-3 mb-6">
        <div className="w-10 h-10 rounded-full bg-primary-100 dark:bg-primary-300/20 flex items-center justify-center">
          <Sparkles className="w-5 h-5 text-primary-500" />
        </div>
        <div>
          <h2 className="text-lg font-semibold">高级配方优化生成</h2>
          <p className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">基于遗传算法多目标优化生成配方方案</p>
        </div>
      </div>

      <Tabs value={inputMode} onValueChange={(v) => setInputMode(v as 'direct' | 'tag')}>
        <TabsList className="mb-6">
          <TabsTrigger value="tag" icon={<Tag className="w-4 h-4" />}>
            标签选择
          </TabsTrigger>
          <TabsTrigger value="direct" icon={<Sliders className="w-4 h-4" />}>
            直接输入
          </TabsTrigger>
        </TabsList>

        <TabsContent value="tag" className="space-y-6">
          <div className="space-y-5">
            <div>
              <label className="text-sm font-medium text-neutral-700 dark:text-neutral-300 block mb-3">
                功效标签（可多选）
              </label>
              <div className="flex flex-wrap gap-2" role="group" aria-label="功效标签选择">
                {EFFECT_OPTIONS.map((effect) => (
                  <button
                    key={effect}
                    onClick={() => toggleEffect(effect)}
                    onKeyDown={(e) => handleEffectKeyDown(e, effect)}
                    role="checkbox"
                    aria-checked={selectedEffects.includes(effect)}
                    aria-label={`功效: ${effect}`}
                    tabIndex={0}
                    className={`px-3 py-1.5 rounded-lg text-sm transition-all focus:outline-none focus:ring-2 focus:ring-primary-500 focus:ring-offset-2 ${
                      selectedEffects.includes(effect)
                        ? 'bg-primary-container text-primary-main shadow-sm shadow-primary-500/20'
                        : 'bg-neutral-100 dark:bg-neutral-700 text-neutral-600 dark:text-neutral-300 hover:bg-neutral-200 dark:hover:bg-neutral-600'
                    }`}
                  >
                    {effect}
                  </button>
                ))}
              </div>
            </div>

            <div>
              <label className="text-sm font-medium text-neutral-700 dark:text-neutral-300 block mb-3">成分类型</label>
              <div className="flex flex-wrap gap-2" role="group" aria-label="成分类型选择">
                {INGREDIENT_TYPE_OPTIONS.map((type) => (
                  <button
                    key={type}
                    onClick={() => toggleIngredientType(type)}
                    onKeyDown={(e) => handleIngredientTypeKeyDown(e, type)}
                    role="checkbox"
                    aria-checked={selectedIngredientTypes.includes(type)}
                    aria-label={`成分类型: ${type}`}
                    tabIndex={0}
                    className={`px-3 py-1.5 rounded-lg text-sm transition-all focus:outline-none focus:ring-2 focus:ring-accent-500 focus:ring-offset-2 ${
                      selectedIngredientTypes.includes(type)
                        ? 'bg-accent-container text-accent-main shadow-sm shadow-accent-500/20'
                        : 'bg-neutral-100 dark:bg-neutral-700 text-neutral-600 dark:text-neutral-300 hover:bg-neutral-200 dark:hover:bg-neutral-600'
                    }`}
                  >
                    {type}
                  </button>
                ))}
              </div>
            </div>

            <div>
              <label className="text-sm font-medium text-neutral-700 dark:text-neutral-300 block mb-3">口感偏好</label>
              <div className="flex flex-wrap gap-2" role="group" aria-label="口感偏好选择">
                {TASTE_OPTIONS.map((taste) => (
                  <button
                    key={taste}
                    onClick={() => toggleTaste(taste)}
                    onKeyDown={(e) => handleTasteKeyDown(e, taste)}
                    role="checkbox"
                    aria-checked={selectedTastes.includes(taste)}
                    aria-label={`口感: ${taste}`}
                    tabIndex={0}
                    className={`px-3 py-1.5 rounded-lg text-sm transition-all focus:outline-none focus:ring-2 focus:ring-warning-500 focus:ring-offset-2 ${
                      selectedTastes.includes(taste)
                        ? 'bg-warning-500 text-white shadow-sm shadow-warning-500/20'
                        : 'bg-neutral-100 dark:bg-neutral-700 text-neutral-600 dark:text-neutral-300 hover:bg-neutral-200 dark:hover:bg-neutral-600'
                    }`}
                  >
                    <Cherry className="w-3 h-3 inline mr-1" />
                    {taste}
                  </button>
                ))}
              </div>
            </div>

            <div>
              <label className="text-sm font-medium text-neutral-700 dark:text-neutral-300 block mb-3">安全等级</label>
              <div className="flex flex-wrap gap-2" role="group" aria-label="安全等级选择">
                {SAFETY_LEVEL_OPTIONS.map((level) => (
                  <button
                    key={level}
                    onClick={() => setSelectedSafetyLevel(level === selectedSafetyLevel ? '' : level)}
                    onKeyDown={(e) => handleSafetyLevelKeyDown(e, level)}
                    role="checkbox"
                    aria-checked={selectedSafetyLevel === level}
                    aria-label={`安全等级: ${level}`}
                    tabIndex={0}
                    className={`px-3 py-1.5 rounded-lg text-sm transition-all focus:outline-none focus:ring-2 focus:ring-success-500 focus:ring-offset-2 ${
                      selectedSafetyLevel === level
                        ? 'bg-success-500 text-white shadow-sm shadow-success-500/20'
                        : 'bg-neutral-100 dark:bg-neutral-700 text-neutral-600 dark:text-neutral-300 hover:bg-neutral-200 dark:hover:bg-neutral-600'
                    }`}
                  >
                    <Shield className="w-3 h-3 inline mr-1" />
                    {level}
                  </button>
                ))}
              </div>
            </div>
          </div>
        </TabsContent>

        <TabsContent value="direct">
          <div className="space-y-4">
            <div>
              <label className="text-sm font-medium text-neutral-700 dark:text-neutral-300 block mb-2">
                输入目标功效描述
              </label>
              <textarea
                value={directInput}
                onChange={(e) => setDirectInput(e.target.value)}
                placeholder="例如：降血糖、抗疲劳、补气养阴"
                className="input resize-none w-full"
                rows={3}
              />
              <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-1">多个功效用逗号分隔</p>
            </div>
          </div>
        </TabsContent>
      </Tabs>

      <div className="mt-6 pt-6 border-t border-neutral-200 dark:border-neutral-700 space-y-5">
        <div>
          <div className="flex items-center justify-between mb-3">
            <label className="text-sm font-medium text-neutral-700 dark:text-neutral-300">优先级权重调节</label>
            <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">调整各项权重影响配方生成倾向</span>
          </div>
          <div className="space-y-4">
            {[
              { key: 'synergy', label: '协同效应', color: 'primary' },
              { key: 'taste', label: '口感偏好', color: 'accent' },
              { key: 'stability', label: '稳定性', color: 'warning' },
              { key: 'safety', label: '安全性', color: 'success' },
            ].map((item) => (
              <div key={item.key} className="space-y-2">
                <div className="flex items-center justify-between">
                  <span className="text-sm text-neutral-600 dark:text-neutral-400">{item.label}</span>
                  <span className="text-sm font-medium text-neutral-800 dark:text-neutral-200">
                    {(priorityValues[item.key] * 100).toFixed(0)}%
                  </span>
                </div>
                <Slider
                  value={priorityValues[item.key]}
                  min={0}
                  max={1}
                  step={0.05}
                  onChange={(value) => handlePriorityChange(item.key, value)}
                  className="w-full"
                />
              </div>
            ))}
          </div>
        </div>

        <div>
          <label className="text-sm font-medium text-neutral-700 dark:text-neutral-300 block mb-3">约束条件</label>
          <div className="space-y-4">
            <div>
              <div className="flex items-center justify-between mb-2">
                <span className="text-sm text-neutral-600 dark:text-neutral-400">最大成分数</span>
                <span className="text-sm font-medium text-neutral-800 dark:text-neutral-200">{maxIngredients}</span>
              </div>
              <Slider
                value={maxIngredients}
                min={3}
                max={20}
                step={1}
                onChange={(value) => setMaxIngredients(value)}
                className="w-full"
              />
            </div>

            <div>
              <label className="text-sm text-neutral-600 dark:text-neutral-400 block mb-2">排除成分</label>
              <div className="flex gap-2">
                <Input
                  value={excludedInput}
                  onChange={(e) => setExcludedInput(e.target.value)}
                  placeholder="输入要排除的成分，多个用逗号分隔"
                  className="flex-1"
                  onKeyDown={(e) => {
                    if (e.key === 'Enter') {
                      e.preventDefault();
                      addExcludedIngredient();
                    }
                  }}
                />
                <Button variant="secondary" size="sm" onClick={addExcludedIngredient}>
                  添加
                </Button>
              </div>
              {excludedIngredients.length > 0 && (
                <div className="flex flex-wrap gap-2 mt-2">
                  {excludedIngredients.map((item) => (
                    <Badge key={item} variant="danger" className="flex items-center gap-1">
                      {item}
                      <X
                        className="w-3 h-3 cursor-pointer hover:text-danger-600"
                        onClick={() => removeExcludedIngredient(item)}
                      />
                    </Badge>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      <div className="mt-6">
        {progress.stage !== 'idle' && (
          <GenerationProgressPanel progress={progress} onCancel={handleCancel} showCancelButton={progress.canCancel} />
        )}
        <Button
          ref={generateButtonRef}
          disabled={!canGenerate || mutation.isPending}
          onClick={() => mutation.mutate()}
          loading={mutation.isPending}
          icon={<Sparkles className="w-4 h-4" />}
          className="w-full"
          aria-describedby="generate-button-hint"
        >
          {mutation.isPending ? '生成中...' : '开始生成'}
        </Button>
        <span id="generate-button-hint" className="sr-only">
          {canGenerate ? '点击或回车生成配方' : '请先选择功效标签或输入功效描述'}
        </span>
      </div>

      {mutation.isError && (
        <div className="mt-4 p-4 bg-danger-50 dark:bg-danger-500/10 border border-danger-200 dark:border-danger-500/20 rounded-lg">
          <div className="flex items-center gap-2 text-danger-600 dark:text-danger-600">
            <AlertTriangle className="w-4 h-4" />
            <span className="text-sm">
              生成失败：
              {mutation.error instanceof Error && typeof mutation.error.message === 'string'
                ? mutation.error.message
                : '请检查输入后重试'}
            </span>
          </div>
        </div>
      )}

      {candidates && candidates.length > 0 && (
        <section className="mt-6 space-y-4" aria-labelledby="candidates-heading">
          <div className="flex items-center justify-between">
            <h3 id="candidates-heading" className="text-base font-semibold text-neutral-900 dark:text-neutral-100">
              生成 {candidates.length} 个候选方案
            </h3>
            <Badge variant="primary">
              {data?.generator === 'ga_optimizer'
                ? '遗传算法优化'
                : data?.generator === 'rule_engine_fallback'
                  ? '规则引擎生成'
                  : 'AI 优化生成'}
            </Badge>
          </div>
          <ul className="space-y-4" role="list" aria-label="配方候选方案列表">
            {candidates.map((candidate, index) => (
              <li key={index}>
                <Card hoverable className="p-4 border border-neutral-100 dark:border-neutral-700">
                  <div className="flex items-start justify-between mb-3">
                    <div>
                      <h4 className="font-semibold text-neutral-900 dark:text-neutral-100">
                        {typeof candidate.formula_name === 'string' ? candidate.formula_name : '未知配方'}
                      </h4>
                      <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-1">
                        协同 {(candidate.synergy_score ?? 0).toFixed(2)} | 口感{' '}
                        {(candidate.taste_score ?? 0).toFixed(2)} | 稳定性 {(candidate.stability_score ?? 0).toFixed(2)}
                      </p>
                    </div>
                    <div className="text-right">
                      <div
                        className={`text-xl font-bold ${
                          (candidate.overall_score ?? 0) >= 0.8
                            ? 'text-success-500'
                            : (candidate.overall_score ?? 0) >= 0.6
                              ? 'text-warning-500'
                              : 'text-danger-500'
                        }`}
                      >
                        {(candidate.overall_score ?? 0).toFixed(2)}
                      </div>
                      <div className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">综合评分</div>
                    </div>
                  </div>

                  <div className="mb-3">
                    <span className="text-xs font-medium text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">药材组成：</span>
                    <div className="flex flex-wrap gap-1 mt-1">
                      {candidate.herb_combination?.map((herb, i) => (
                        <Badge key={i} variant="neutral" size="sm">
                          {typeof herb.name === 'string' ? herb.name : '未知药材'}
                        </Badge>
                      ))}
                    </div>
                  </div>

                  <div className="flex items-center gap-2" role="status" aria-label="安全状态">
                    {candidate.safety_passed ? (
                      <Badge variant="success" className="flex items-center gap-1" role="img" aria-label="安全验证通过">
                        <CheckCircle className="w-3 h-3" />
                        安全
                      </Badge>
                    ) : (
                      <Badge variant="warning" className="flex items-center gap-1" role="img" aria-label="需要注意">
                        <AlertTriangle className="w-3 h-3" />
                        需关注
                      </Badge>
                    )}
                  </div>
                </Card>
              </li>
            ))}
          </ul>
        </section>
      )}
    </Card>
  );
}

export default AdvancedGeneratePanel;

import React, { useState, useCallback, useEffect } from 'react'
import {
  Microscope, BarChart3, Dna, Zap, FlaskConical, Shield,
  ChevronDown, ChevronUp, Download, Loader2, CheckCircle2,
  AlertTriangle, Layers, Target, Atom, Save, History,
  Trash2, Edit3, X, Clock, Tag, Database,
} from 'lucide-react'
import { peptideAnalysisApi, type PeptideAnalysisData } from '@/api/ai'
import { logger } from '@/utils/safeLogger'
import { useToast } from '@/components/ui'


interface PeptideAnalysisResult {
  sequence?: string;
  details?: {
    id: number;
    dimension_type: 'basic' | 'structure' | 'physicochemical' | 'bioactivity' | 'safety' | 'overall';
    data: Record<string, unknown>;
    created_at: string;
  }[];
  overall_scores?: Record<string, unknown>;
  basic_properties?: Record<string, unknown>;
  secondary_structure?: Record<string, unknown> & {
    percentages?: {
      alpha_helix?: number;
      beta_sheet?: number;
      random_coil?: number;
    };
    predicted_sequence?: string;
  };
  bioactivity_predictions?: Record<string, unknown>;
  safety_assessment?: Record<string, unknown> & {
    risk_level?: 'low' | 'medium' | 'high';
    safety_score?: number;
    penalties?: string[];
    immunogenicity_risk?: number;
    allergenicity_risk?: number;
    protease_cleavage_sites?: string[];
    recommended_storage_conditions?: string;
  };
}


interface DeepAnalysisProps {
  initialSequence?: string
  onAnalysisComplete?: (result: PeptideAnalysisResult) => void
}

export function AdvancedPeptideAnalyzer({ initialSequence = '', onAnalysisComplete }: DeepAnalysisProps) {
  const { addToast } = useToast()
  const [activeMode, setActiveMode] = useState<'single' | 'batch' | 'pareto' | 'synergy' | 'solubility'>('single')
  const [sequence, setSequence] = useState(initialSequence)
  const [loading, setLoading] = useState(false)
  const [result, setResult] = useState<PeptideAnalysisResult | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [expandedSections, setExpandedSections] = useState<Record<string, boolean>>({
    basic: true, structure: true, bioactivity: true, safety: true,
  })

  // 新增状态：数据库集成
  const [currentAnalysisId, setCurrentAnalysisId] = useState<number | null>(null)
  const [saving, setSaving] = useState(false)
  const [showHistoryPanel, setShowHistoryPanel] = useState(false)
  const [historyList, setHistoryList] = useState<PeptideAnalysisData[]>([])
  const [historyLoading, setHistoryLoading] = useState(false)
  const [historyPage, setHistoryPage] = useState(1)
  const [historyTotal, setHistoryTotal] = useState(0)
  const [editingNotes, setEditingNotes] = useState<string>('')
  const [editingTags, setEditingTags] = useState<string>('')
  const [isEditing, setIsEditing] = useState(false)
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false)
  const [deleteLoading, setDeleteLoading] = useState(false)

  // 加载历史分析列表
  const loadHistory = useCallback(async (page = 1) => {
    setHistoryLoading(true)
    try {
      const response = await peptideAnalysisApi.listAnalyses({ page, page_size: 20 })
      setHistoryList(response.items)
      setHistoryTotal(response.total)
      setHistoryPage(page)
    } catch (err: any) {
      logger.error('加载历史失败:', err)
    } finally {
      setHistoryLoading(false)
    }
  }, [])

  // 组件挂载时自动加载历史
  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    loadHistory()
  }, [loadHistory])

  // 保存当前分析到数据库
  const handleSaveAnalysis = async () => {
    if (!result || !sequence) return

    setSaving(true)
    try {
      const response = await peptideAnalysisApi.createAnalysis({
        sequence,
        analysis_mode: 'deep',
        tags: [],
        notes: '',
      })

      setCurrentAnalysisId(response.data.id)

      // 显示成功提示（可替换为Toast）
      addToast({ type: 'success', title: '保存成功', message: `分析已保存！ID: ${response.data.id}` })

      // 刷新历史列表
      await loadHistory(1)
    } catch (err: any) {
      logger.error('保存失败:', err)
      addToast({ type: 'error', title: '保存失败', message: err.message || '未知错误' })
    } finally {
      setSaving(false)
    }
  }

  // 从历史加载分析详情
  const handleLoadFromHistory = async (id: number) => {
    try {
      const analysis = await peptideAnalysisApi.getAnalysis(id)

      // 更新界面状态
      setSequence(analysis.sequence)
      setCurrentAnalysisId(analysis.id)
      setEditingNotes(analysis.notes || '')
      setEditingTags((analysis.tags || []).join(', '))

      // 如果有详细数据，恢复显示
      if (analysis.details && analysis.details.length > 0) {
        // 将details转换为result格式（简化版）
        const reconstructedResult = {
          sequence: analysis.sequence,
          details: analysis.details,
          basic_properties: analysis.details.find(d => d.dimension_type === 'basic')?.data || {},
          secondary_structure: analysis.details.find(d => d.dimension_type === 'structure')?.data || {},
          bioactivity_predictions: analysis.details.find(d => d.dimension_type === 'bioactivity')?.data || {},
          safety_assessment: analysis.details.find(d => d.dimension_type === 'safety')?.data || {},
          overall_scores: analysis.details.find(d => d.dimension_type === 'overall')?.data || {},
        }
        setResult(reconstructedResult)
      }

      setShowHistoryPanel(false)
    } catch (err: any) {
      logger.error('加载失败:', err)
      addToast({ type: 'error', title: '加载失败', message: err.message || '未知错误' })
    }
  }

  // 更新备注和标签
  const handleUpdateMetadata = async () => {
    if (!currentAnalysisId) return

    try {
      await peptideAnalysisApi.updateAnalysis(currentAnalysisId, {
        tags: editingTags.split(',').map(t => t.trim()).filter(Boolean),
        notes: editingNotes,
      })

      setIsEditing(false)
      addToast({ type: 'success', title: '更新成功', message: '分析数据已更新' })
      await loadHistory(historyPage)
    } catch (err: any) {
      logger.error('更新失败:', err)
      addToast({ type: 'error', title: '更新失败', message: '请重试' })
    }
  }

  // 删除分析记录
  const handleDeleteAnalysis = async () => {
    if (!currentAnalysisId) return

    setDeleteLoading(true)
    try {
      await peptideAnalysisApi.deleteAnalysis(currentAnalysisId)

      // 重置状态
      setCurrentAnalysisId(null)
      setResult(null)
      setSequence('')
      setShowDeleteConfirm(false)

      addToast({ type: 'success', title: '删除成功', message: '分析记录已删除' })
      await loadHistory(historyPage)
    } catch (err: any) {
      logger.error('删除失败:', err)
      addToast({ type: 'error', title: '删除失败', message: '请重试' })
    } finally {
      setDeleteLoading(false)
    }
  }

  const handleDeepAnalysis = async () => {
    if (!sequence || sequence.length < 2) {
      setError('请输入有效的肽序列（至少2个氨基酸）')
      return
    }

    setLoading(true)
    setError(null)
    setResult(null)

    try {
      const response = await fetch('/api/v1/ai/peptide/advanced/analyze/deep', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${localStorage.getItem('access_token') || ''}`,
        },
        body: JSON.stringify({ sequence }),
      })

      if (!response.ok) {
        const errorText = await response.text()
        let errorMessage = `分析失败 (${response.status})`

        try {
          const errorData = JSON.parse(errorText)
          errorMessage = errorData.detail || errorMessage
        } catch {
          if (errorText) {
            errorMessage = `${errorMessage}: ${errorText.slice(0, 200)}`
          }
        }

        throw new Error(errorMessage)
      }

      const data = await response.json()

      if (data.success) {
        setResult(data.data)
        onAnalysisComplete?.(data.data)
      } else {
        setError(data.detail || '分析失败：服务器返回异常')
      }
    } catch (err: any) {
      logger.error('深度分析失败:', err)
      setError(err.message || '网络错误，请检查连接后重试')
    } finally {
      setLoading(false)
    }
  }

  const toggleSection = (section: string) => {
    setExpandedSections(prev => ({ ...prev, [section]: !prev[section] }))
  }

  const renderScoreBar = (label: string, score: number, color: string) => (
    <div className="flex items-center gap-3 mb-2">
      <span className="text-sm text-neutral-600 w-32">{label}</span>
      <div className="flex-1 h-2 bg-neutral-200 dark:bg-neutral-700 rounded-full overflow-hidden">
        <div
          className={`h-full rounded-full transition-all duration-500 bg-${color}-500`}
          style={{ width: `${Math.min(score * 100, 100)}%` }}
        />
      </div>
      <span className="text-sm font-mono font-semibold w-12 text-right">
        {(score * 100).toFixed(1)}%
      </span>
    </div>
  )

  const renderPropertyGrid = (props: Record<string, any>) => (
    <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-3">
      {Object.entries(props).map(([key, value]) => (
        <div key={key} className="p-3 bg-neutral-50 dark:bg-neutral-800 rounded-lg">
          <div className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] capitalize">{key.replace(/_/g, ' ')}</div>
          <div className="text-lg font-semibold mt-1">
            {typeof value === 'number' ? value.toFixed(2) : String(value)}
          </div>
        </div>
      ))}
    </div>
  )

  return (
    <div className="bg-white dark:bg-neutral-900 rounded-xl shadow-lg border border-neutral-200 dark:border-neutral-700 overflow-hidden">
      {/* Header */}
      <div className="p-6 border-b border-neutral-200 dark:border-neutral-700 bg-gradient-to-r from-accent-500 via-accent-500 to-danger-500">
        <div className="flex items-center gap-3">
          <div className="p-3 bg-white dark:bg-neutral-900/20 rounded-xl backdrop-blur">
            <Microscope className="w-7 h-7 text-white" />
          </div>
          <div>
            <h2 className="text-2xl font-bold text-white">高级肽分析引擎</h2>
            <p className="text-white/80 text-sm">
              二级结构预测 · 理化性质 · 安全性评分
              <span className="text-white/50">（批量 / Pareto / 协同 / 溶解度模式后端未实现，已禁用）</span>
            </p>
          </div>
        </div>

        {/* Mode Tabs */}
        {/* ready=false 的 4 个模式后端还没有对应端点，必须显式禁用，
            否则用户点进去只看到"即将上线"，误以为功能已完成。 */}
        <div className="flex gap-2 mt-5 flex-wrap">
          {[
            { id: 'single', icon: Microscope, label: '深度分析', ready: true },
            { id: 'batch', icon: Layers, label: '批量分析', ready: false },
            { id: 'pareto', icon: Target, label: 'Pareto 优化', ready: false },
            { id: 'synergy', icon: Dna, label: '协同分析', ready: false },
            { id: 'solubility', icon: FlaskConical, label: '溶解度曲线', ready: false },
          ].map(({ id, icon: Icon, label, ready }) => (
            <button
              key={id}
              onClick={() => setActiveMode(id as 'single' | 'batch' | 'pareto' | 'synergy' | 'solubility')}
              disabled={!ready}
              title={ready ? undefined : '该模式后端端点尚未实现，暂不可用'}
              aria-disabled={!ready}
              className={`px-4 py-2 rounded-lg font-medium transition-all flex items-center gap-2 ${
                activeMode === id
                  ? 'bg-white dark:bg-neutral-900 text-accent-600 shadow-md'
                  : ready
                    ? 'bg-white/10 text-white hover:bg-white/20'
                    : 'bg-white/5 text-white/40 cursor-not-allowed'
              }`}
            >
              <Icon className="w-4 h-4" />
              {label}
              {!ready && (
                <span className="text-[10px] px-1.5 py-0.5 rounded bg-white/10 text-white/50">规划中</span>
              )}
            </button>
          ))}
        </div>
      </div>

      <div className="p-6">
        {/* Single Analysis Mode */}
        {activeMode === 'single' && (
          <div className="space-y-6">
            {/* Input */}
            <div className="flex gap-3">
              <input
                type="text"
                value={sequence}
                onChange={(e) => setSequence(e.target.value.toUpperCase())}
                placeholder="输入肽序列，如 VLGYT 或 LRPFFY..."
                className="flex-1 px-4 py-3 border-2 border-neutral-300 dark:border-neutral-600 rounded-lg
                         bg-white dark:bg-neutral-800 text-neutral-900 dark:text-white font-mono text-lg
                         focus:border-accent-500 focus:ring-2 focus:ring-accent-200 transition-all"
              />
              <button
                onClick={handleDeepAnalysis}
                disabled={loading || !sequence}
                className="px-8 py-3 bg-gradient-to-r from-[var(--color-accent-surface)] to-[var(--color-danger-surface-deep)] text-white rounded-lg
                         font-semibold hover:shadow-lg disabled:opacity-50 flex items-center gap-2"
              >
                {loading ? <Loader2 className="w-5 h-5 animate-spin" /> : <Microscope className="w-5 h-5" />}
                深度分析
              </button>
            </div>

            {/* Error */}
            {error && (
              <div className="p-4 bg-error-50 dark:bg-error-300/20 border border-error-200 dark:border-error-800 rounded-lg flex items-start gap-3">
                <AlertTriangle className="w-5 h-5 text-error-500 mt-0.5" />
                <div className="text-error-700 dark:text-error-600">{error}</div>
              </div>
            )}

            {/* Results */}
            {result && (
              <div className="space-y-4">
                {/* 数据库操作工具栏 */}
                <div className="flex items-center justify-between p-4 bg-gradient-to-r from-secondary-50 to-accent-50 dark:from-secondary-900/20 dark:to-accent-900/20 rounded-lg border border-secondary-200 dark:border-secondary-800">
                  <div className="flex items-center gap-3">
                    {currentAnalysisId ? (
                      <>
                        <Database className="w-5 h-5 text-success-600" />
                        <span className="text-sm font-medium text-neutral-700 dark:text-neutral-300">
                          已保存 (ID: {currentAnalysisId})
                        </span>
                      </>
                    ) : (
                      <>
                        <Save className="w-5 h-5 text-warning-600" />
                        <span className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">分析完成，可保存到数据库</span>
                      </>
                    )}
                  </div>

                  <div className="flex items-center gap-2">
                    {/* 保存按钮（未保存时显示） */}
                    {!currentAnalysisId && (
                      <button
                        onClick={handleSaveAnalysis}
                        disabled={saving}
                        className="px-4 py-2 bg-success-600 text-white rounded-lg hover:bg-success-700 disabled:opacity-50 flex items-center gap-2 text-sm"
                      >
                        {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
                        保存到数据库
                      </button>
                    )}

                    {/* 已保存后的操作按钮 */}
                    {currentAnalysisId && (
                      <>
                        <button
                          onClick={() => setIsEditing(!isEditing)}
                          className="px-3 py-2 bg-secondary-100 text-secondary-700 rounded-lg hover:bg-secondary-200 flex items-center gap-1.5 text-sm"
                        >
                          <Edit3 className="w-4 h-4" />
                          编辑备注
                        </button>
                        <button
                          onClick={() => setShowDeleteConfirm(true)}
                          className="px-3 py-2 bg-error-100 text-error-700 rounded-lg hover:bg-error-200 flex items-center gap-1.5 text-sm"
                        >
                          <Trash2 className="w-4 h-4" />
                          删除
                        </button>
                      </>
                    )}

                    {/* 历史记录按钮 */}
                    <button
                      onClick={() => setShowHistoryPanel(!showHistoryPanel)}
                      className="px-3 py-2 bg-neutral-100 text-neutral-700 dark:bg-neutral-800 dark:text-neutral-300 rounded-lg hover:bg-neutral-200 dark:hover:bg-neutral-700 flex items-center gap-1.5 text-sm"
                    >
                      <History className="w-4 h-4" />
                      历史记录 ({historyTotal})
                    </button>
                  </div>
                </div>

                {/* 编辑备注和标签的表单 */}
                {isEditing && currentAnalysisId && (
                  <div className="p-4 bg-warning-50 dark:bg-warning-300/20 border border-warning-200 dark:border-warning-800 rounded-lg space-y-3">
                    <div className="font-medium text-warning-800 dark:text-warning-200">编辑元数据</div>
                    <input
                      type="text"
                      value={editingTags}
                      onChange={(e) => setEditingTags(e.target.value)}
                      placeholder="标签（逗号分隔）"
                      className="w-full px-3 py-2 border border-warning-300 dark:border-warning-700 rounded bg-white dark:bg-neutral-800 text-sm"
                    />
                    <textarea
                      value={editingNotes}
                      onChange={(e) => setEditingNotes(e.target.value)}
                      placeholder="备注信息..."
                      rows={2}
                      className="w-full px-3 py-2 border border-warning-300 dark:border-warning-700 rounded bg-white dark:bg-neutral-800 text-sm resize-none"
                    />
                    <div className="flex gap-2 justify-end">
                      <button
                        onClick={() => setIsEditing(false)}
                        className="px-3 py-1.5 text-sm text-neutral-600 hover:text-neutral-800"
                      >
                        取消
                      </button>
                      <button
                        onClick={handleUpdateMetadata}
                        className="px-4 py-1.5 bg-warning-600 text-white rounded text-sm hover:bg-warning-700"
                      >
                        保存修改
                      </button>
                    </div>
                  </div>
                )}

                {/* 删除确认对话框 */}
                {showDeleteConfirm && (
                  <div className="p-4 bg-error-50 dark:bg-error-300/20 border border-error-200 dark:border-error-800 rounded-lg space-y-3">
                    <div className="font-medium text-error-800 dark:text-error-200 flex items-center gap-2">
                      <AlertTriangle className="w-5 h-5" />
                      确认删除此分析记录？
                    </div>
                    <p className="text-sm text-error-600 dark:text-error-600">
                      删除后数据将移至回收站，可在管理后台恢复。此操作不可撤销。
                    </p>
                    <div className="flex gap-2 justify-end">
                      <button
                        onClick={() => setShowDeleteConfirm(false)}
                        disabled={deleteLoading}
                        className="px-3 py-1.5 text-sm text-neutral-600 hover:text-neutral-800"
                      >
                        取消
                      </button>
                      <button
                        onClick={handleDeleteAnalysis}
                        disabled={deleteLoading}
                        className="px-4 py-1.5 bg-error-600 text-white rounded text-sm hover:bg-error-700 disabled:opacity-50 flex items-center gap-1.5"
                      >
                        {deleteLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Trash2 className="w-4 h-4" />}
                        确认删除
                      </button>
                    </div>
                  </div>
                )}

                {/* 历史记录侧边栏 */}
                {showHistoryPanel && (
                  <div className="border border-neutral-200 dark:border-neutral-700 rounded-lg overflow-hidden">
                    <div className="px-4 py-3 bg-neutral-50 dark:bg-neutral-800 flex items-center justify-between">
                      <div className="font-semibold text-neutral-900 dark:text-white flex items-center gap-2">
                        <Clock className="w-5 h-5" />
                        我的历史分析 ({historyTotal}条)
                      </div>
                      <button
                        onClick={() => setShowHistoryPanel(false)}
                        className="p-1 hover:bg-neutral-200 dark:hover:bg-neutral-700 rounded"
                      >
                        <X className="w-5 h-5" />
                      </button>
                    </div>

                    <div className="max-h-96 overflow-y-auto">
                      {historyLoading ? (
                        <div className="p-8 text-center text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                          <Loader2 className="w-8 h-8 animate-spin mx-auto mb-2" />
                          加载中...
                        </div>
                      ) : historyList.length === 0 ? (
                        <div className="p-8 text-center text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                          <Database className="w-12 h-12 mx-auto mb-2 opacity-30" />
                          暂无历史记录
                        </div>
                      ) : (
                        <div className="divide-y divide-neutral-200 dark:divide-neutral-700">
                          {historyList.map((item) => (
                            <button
                              key={item.id}
                              onClick={() => handleLoadFromHistory(item.id)}
                              className="w-full px-4 py-3 hover:bg-neutral-50 dark:hover:bg-neutral-800 text-left transition-colors"
                            >
                              <div className="font-mono font-semibold text-neutral-900 dark:text-white">
                                {item.sequence}
                              </div>
                              <div className="flex items-center gap-3 mt-1 text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                                <span>{item.analysis_mode}</span>
                                <span>•</span>
                                <span>{new Date(item.created_at).toLocaleDateString()}</span>
                                {(item.tags || []).length > 0 && (
                                  <>
                                    <span>•</span>
                                    <span className="flex items-center gap-1">
                                      <Tag className="w-3 h-3" />
                                      {item.tags.slice(0, 2).join(', ')}
                                      {item.tags.length > 2 && `+${item.tags.length - 2}`}
                                    </span>
                                  </>
                                )}
                              </div>
                            </button>
                          ))}
                        </div>
                      )}
                    </div>

                    {/* 分页控件 */}
                    {historyTotal > 20 && (
                      <div className="px-4 py-3 bg-neutral-50 dark:bg-neutral-800 border-t border-neutral-200 dark:border-neutral-700 flex items-center justify-between text-sm">
                        <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                          第 {(historyPage - 1) * 20 + 1}-{Math.min(historyPage * 20, historyTotal)} 条，共 {historyTotal} 条
                        </span>
                        <div className="flex gap-2">
                          <button
                            onClick={() => loadHistory(historyPage - 1)}
                            disabled={historyPage <= 1}
                            className="px-3 py-1 border rounded disabled:opacity-50 hover:bg-neutral-100 dark:hover:bg-neutral-700"
                          >
                            上一页
                          </button>
                          <button
                            onClick={() => loadHistory(historyPage + 1)}
                            disabled={historyPage * 20 >= historyTotal}
                            className="px-3 py-1 border rounded disabled:opacity-50 hover:bg-neutral-100 dark:hover:bg-neutral-700"
                          >
                            下一页
                          </button>
                        </div>
                      </div>
                    )}
                  </div>
                )}

                {/* Overall Score Card */}
                <div className="grid grid-cols-5 gap-4 p-5 bg-gradient-to-br from-accent-50 to-danger-50 dark:from-accent-900/20 dark:to-danger-900/20 rounded-xl border border-accent-200 dark:border-accent-800">
                  {[
                    { label: '综合得分', value: Number(result.overall_scores?.composite ?? 0), color: 'purple' },
                    { label: '稳定性', value: Number(result.overall_scores?.stability ?? 0), color: 'blue' },
                    { label: '类药性', value: Number(result.overall_scores?.druglikeness ?? 0), color: 'green' },
                    { label: '生物活性', value: Number(result.overall_scores?.bioactivity ?? 0), color: 'orange' },
                    { label: '安全性', value: Number(result.overall_scores?.safety ?? 0), color: 'emerald' },
                  ].map(({ label, value, color }) => (
                    <div key={label} className="text-center">
                      <div className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-1">{label}</div>
                      <div className={`text-3xl font-bold text-${color}-600`}>
                        {(value * 100).toFixed(1)}<span className="text-lg">%</span>
                      </div>
                      <div className={`mt-1 h-1.5 bg-${color}-200 dark:bg-${color}-900 rounded-full overflow-hidden`}>
                        <div className={`h-full bg-${color}-500 rounded-full`} style={{ width: `${value * 100}%` }} />
                      </div>
                    </div>
                  ))}
                </div>

                {/* Basic Properties */}
                <SectionCard
                  title="基本理化性质"
                  icon={<BarChart3 className="w-5 h-5" />}
                  expanded={expandedSections.basic ?? false}
                  onToggle={() => toggleSection('basic')}
                >
                  {renderPropertyGrid(result.basic_properties || {})}
                </SectionCard>

                {/* Secondary Structure */}
                <SectionCard
                  title="二级结构预测 (Chou-Fasman)"
                  icon={<Dna className="w-5 h-5" />}
                  expanded={expandedSections.structure ?? false}
                  onToggle={() => toggleSection('structure')}
                >
                  {result.secondary_structure && (
                    <div className="space-y-4">
                      {/* Structure Percentages */}
                      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                        {[
                          { type: 'α-Helix', percent: result.secondary_structure.percentages?.alpha_helix ?? 0, color: 'red' },
                          { type: 'β-Sheet', percent: result.secondary_structure.percentages?.beta_sheet ?? 0, color: 'blue' },
                          { type: 'Random Coil', percent: result.secondary_structure.percentages?.random_coil ?? 0, color: 'green' },
                        ].map(({ type, percent, color }) => (
                          <div key={type} className="p-4 bg-neutral-50 dark:bg-neutral-800 rounded-lg text-center">
                            <div className={`text-2xl font-bold text-${color}-600`}>{percent.toFixed(1)}%</div>
                            <div className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-1">{type}</div>
                            <div className={`mt-2 h-2 bg-${color}-200 rounded-full overflow-hidden`}>
                              <div className={`h-full bg-${color}-500 rounded-full transition-all`} style={{ width: `${percent}%` }} />
                            </div>
                          </div>
                        ))}
                      </div>

                      {/* Predicted Sequence Visualization */}
                      {result.secondary_structure.predicted_sequence && (
                        <div className="mt-4">
                          <div className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-2">结构序列可视化</div>
                          <div className="font-mono text-lg flex flex-wrap gap-1">
                            {result.secondary_structure.predicted_sequence.split('').map((char: string, i: number) => (
                              <span
                                key={i}
                                className={`px-2 py-1 rounded ${
                                  char === 'H' ? 'bg-error-100 text-error-700 dark:bg-error-300/25 dark:text-error-600' :
                                  char === 'E' ? 'bg-secondary-100 text-secondary-700 dark:bg-secondary-300/25 dark:text-secondary-700' :
                                  'bg-success-100 text-success-700 dark:bg-success-300/25 dark:text-success-600'
                                }`}
                                title={`${(result.sequence?.[i] ?? '')}${i + 1}: ${char === 'H' ? 'Helix' : char === 'E' ? 'Sheet' : 'Coil'}`}
                              >
                                {result.sequence?.[i] ?? ''}
                              </span>
                            ))}
                          </div>
                        </div>
                      )}
                    </div>
                  )}
                </SectionCard>

                {/* Bioactivity Predictions */}
                <SectionCard
                  title="生物活性预测"
                  icon={<Zap className="w-5 h-5" />}
                  expanded={expandedSections.bioactivity ?? false}
                  onToggle={() => toggleSection('bioactivity')}
                >
                  {result.bioactivity_predictions && (
                    <div className="space-y-3">
                      {Object.entries(result.bioactivity_predictions).map(([activity, data]: [string, any]) => {
                        const score = data.score ?? 0.5
                        const tier = data.tier ?? 'moderate'
                        return (
                          <div key={activity} className="p-4 bg-neutral-50 dark:bg-neutral-800 rounded-lg">
                            <div className="flex justify-between items-center mb-2">
                              <span className="font-medium">{activity}</span>
                              <span className={`px-2 py-0.5 rounded-full text-xs font-medium ${
                                tier === 'excellent' ? 'bg-success-100 text-success-700' :
                                tier === 'good' ? 'bg-secondary-100 text-secondary-700' :
                                tier === 'moderate' ? 'bg-warning-100 text-warning-700' :
                                'bg-error-100 text-error-700'
                              }`}>
                                {tier.toUpperCase()}
                              </span>
                            </div>
                            {renderScoreBar(activity, score, tier === 'excellent' ? 'green' : tier === 'good' ? 'blue' : 'yellow')}
                            {data.potential_applications && (
                              <div className="mt-2 text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                                应用场景: {data.potential_applications.join(', ')}
                              </div>
                            )}
                          </div>
                        )
                      })}
                    </div>
                  )}
                </SectionCard>

                {/* Safety Assessment */}
                <SectionCard
                  title="安全性评估"
                  icon={<Shield className="w-5 h-5" />}
                  expanded={expandedSections.safety ?? false}
                  onToggle={() => toggleSection('safety')}
                >
                  {result.safety_assessment && (() => {
                    const sa = result.safety_assessment;
                    return (
                    <div className="space-y-4">
                      <div className={`p-4 rounded-lg ${
                        sa.risk_level === 'low' ? 'bg-success-50 dark:bg-success-300/20 border border-success-200' :
                        sa.risk_level === 'medium' ? 'bg-warning-50 dark:bg-warning-300/20 border border-warning-200' :
                        'bg-error-50 dark:bg-error-300/20 border border-error-200'
                      }`}>
                        <div className="flex items-center gap-3">
                          {sa.risk_level === 'low' && <CheckCircle2 className="w-6 h-6 text-success-500" />}
                          {sa.risk_level === 'medium' && <AlertTriangle className="w-6 h-6 text-warning-500" />}
                          {sa.risk_level === 'high' && <AlertTriangle className="w-6 h-6 text-error-500" />}
                          <div>
                            <div className="font-semibold">安全等级: {sa.risk_level?.toUpperCase() ?? '-'}</div>
                            <div className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                              {/* safety_score 是 0-1 尺度（后端 advanced_peptide_analyzer.py:884，
                                  阈值 0.8/0.5 对应 low/medium/high），展示为百分数必须 ×100。
                                  原写法 `sa.safety_score ?? 0 * 100` 因 ?? 优先级低于 * 等价于
                                  `sa.safety_score ?? 0`，0.85 会显示成 "0.85%"，比真实值小 100 倍。 */}
                              评分: {((sa.safety_score ?? 0) * 100).toFixed(1)}%
                            </div>
                          </div>
                        </div>
                      </div>

                      {sa.penalties && sa.penalties.length > 0 && (
                        <div className="space-y-2">
                          <div className="text-sm font-medium text-neutral-700">风险因素:</div>
                          {sa.penalties.map((penalty: string, i: number) => (
                            <div key={i} className="flex items-center gap-2 text-sm text-warning-600">
                              <AlertTriangle className="w-4 h-4" />
                              {penalty}
                            </div>
                          ))}
                        </div>
                      )}

                      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-3">
                        {[
                          { label: '免疫原性风险', value: sa.immunogenicity_risk },
                          { label: '过敏风险', value: sa.allergenicity_risk },
                          { label: '蛋白酶位点数', value: sa.protease_cleavage_sites?.length ?? 0 },
                          { label: '推荐储存', value: sa.recommended_storage_conditions ?? '-' },
                        ].map(({ label, value }) => (
                          <div key={label} className="p-3 bg-neutral-50 dark:bg-neutral-800 rounded-lg">
                            <div className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{label}</div>
                            <div className="text-sm font-medium mt-0.5">
                              {typeof value === 'number' ? `${(value * 100).toFixed(1)}%` : value}
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                    );
                  })()}
                </SectionCard>

                {/* Export Button */}
                <div className="flex justify-end pt-4 border-t border-neutral-200 dark:border-neutral-700">
                  <button
                    onClick={() => {
                      const blob = new Blob([JSON.stringify(result, null, 2)], { type: 'application/json' })
                      const url = URL.createObjectURL(blob)
                      const a = document.createElement('a')
                      a.href = url
                      a.download = `peptide_analysis_${sequence}_${Date.now()}.json`
                      a.click()
                    }}
                    className="px-4 py-2 bg-neutral-100 dark:bg-neutral-800 text-neutral-700 dark:text-neutral-300 rounded-lg hover:bg-neutral-200 dark:hover:bg-neutral-700 flex items-center gap-2"
                  >
                    <Download className="w-4 h-4" />
                    导出报告
                  </button>
                </div>
              </div>
            )}
          </div>
        )}

        {/* 非 single 模式的兜底展示。模式按钮已 disabled，正常流程进不来；
            保留是为了状态被外部改动时不渲染空白。 */}
        {activeMode !== 'single' && (
          <div className="text-center py-16 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
            <Atom className="w-16 h-16 mx-auto mb-4 opacity-30" />
            <h3 className="text-lg font-medium mb-2 text-[color:var(--text-body)] dark:text-[color:var(--text-primary)]">
              「{activeMode}」模式后端尚未实现
            </h3>
            <p className="text-sm">该模式对应的服务端端点不存在，已禁用对应按钮，请勿通过其它方式进入。</p>
            <button
              onClick={() => setActiveMode('single')}
              className="mt-4 px-4 py-2 text-accent-600 hover:bg-accent-50 rounded-lg"
            >
              返回深度分析模式
            </button>
          </div>
        )}
      </div>
    </div>
  )
}

function SectionCard({
  title,
  icon,
  expanded,
  onToggle,
  children,
}: {
  title: string
  icon: React.ReactNode
  expanded: boolean
  onToggle: () => void
  children: React.ReactNode
}) {
  return (
    <div className="border border-neutral-200 dark:border-neutral-700 rounded-lg overflow-hidden">
      <button
        onClick={onToggle}
        className="w-full px-5 py-4 flex items-center justify-between bg-neutral-50 dark:bg-neutral-800 hover:bg-neutral-100 dark:hover:bg-neutral-750 transition-colors"
      >
        <div className="flex items-center gap-3">
          {icon}
          <h3 className="font-semibold text-neutral-900 dark:text-white">{title}</h3>
        </div>
        {expanded ? <ChevronUp className="w-5 h-5 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" /> : <ChevronDown className="w-5 h-5 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />}
      </button>
      {expanded && (
        <div className="px-5 py-4 bg-white dark:bg-neutral-900">
          {children}
        </div>
      )}
    </div>
  )
}

import React, { useState, useCallback, useEffect } from 'react'
import { Sparkles, Atom, Zap, RefreshCw, CheckCircle, AlertCircle, Loader2, ChevronDown, ChevronUp, Save, FolderOpen, Archive, Eye } from 'lucide-react'
import { peptideDesignApi } from '@/api/ai'
import type { PeptideResult, OptimizedPeptide, PepinventStatusResponse, PeptideDesignData } from '@/api/ai'
import { logger } from '@/utils/safeLogger'
import { useToast } from '@/components/ui'
import { generateSimulatedPeptides } from '@/components/ai/features/services/simulatedPeptideGenerator'


interface AdvancedPeptideDesignProps {
  onPeptidesGenerated?: (peptides: PeptideResult[]) => void
  className?: string
}

const AMINO_ACIDS = 'ACDEFGHIKLMNPQRSTVWY'
function randomMutate(seq: string, n: number): string {
  let s = seq
  for (let i = 0; i < n && s.length > 0; i++) {
    const pos = Math.floor(Math.random() * s.length)
    s = s.substring(0, pos) + AMINO_ACIDS[Math.floor(Math.random() * AMINO_ACIDS.length)] + s.substring(pos + 1)
  }
  return s
}

const TARGET_EFFECTS = [
  { id: 'ACE抑制', label: 'ACE 抑制', message: '降血压活性', color: 'blue' },
  { id: '抗氧化', label: '抗氧化', message: '清除自由基', color: 'green' },
  { id: 'DPP-IV抑制', label: 'DPP-IV 抑制', message: '降血糖活性', color: 'purple' },
  { id: '增强渗透性', label: '膜渗透性', message: '提高生物利用度', color: 'orange' },
  { id: '提高稳定性', label: '结构稳定', message: '增强热稳定性', color: 'red' },
]

const OPTIMIZATION_GOALS = [
  { id: 'ACE_inhibitory', label: 'ACE 抑制活性', defaultWeight: 0.4 },
  { id: 'antioxidant', label: '抗氧化能力', defaultWeight: 0.3 },
  { id: 'permeability', label: '膜渗透性', defaultWeight: 0.2 },
  { id: 'stability', label: '结构稳定性', defaultWeight: 0.1 },
]

export function AdvancedPeptideDesign({ onPeptidesGenerated, className = '' }: AdvancedPeptideDesignProps) {
  const { addToast } = useToast()
  const [activeTab, setActiveTab] = useState<'generate' | 'optimize' | 'sample'>('generate')
  const [mainView, setMainView] = useState<'design' | 'projects'>('design')  // 新增：主视图切换
  const [selectedEffects, setSelectedEffects] = useState<string[]>(['ACE抑制'])
  const [maxCandidates, setMaxCandidates] = useState(5)
  const [loading, setLoading] = useState(false)
  const [results, setResults] = useState<{
    peptides?: PeptideResult[]
    optimized?: OptimizedPeptide[]
    diversityMetrics?: Record<string, number>
    generationMethod?: string
    processingTime?: number
  } | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [serviceStatus, setServiceStatus] = useState<PepinventStatusResponse | null>(null)
  const [showDetails, setShowDetails] = useState<Record<string, boolean>>({})

  // 新增状态：项目管理
  const [currentProjectId, setCurrentProjectId] = useState<number | null>(null)
  const [savingProject, setSavingProject] = useState(false)
  const [projectList, setProjectList] = useState<PeptideDesignData[]>([])
  const [projectLoading, setProjectLoading] = useState(false)
  const [projectPage, setProjectPage] = useState(1)
  const [projectTotal, setProjectTotal] = useState(0)
  const [statusFilter, setStatusFilter] = useState<string>('')
  const [selectedProject, setSelectedProject] = useState<PeptideDesignData | null>(null)

  // 加载项目列表
  const loadProjects = useCallback(async (page = 1, status = '') => {
    setProjectLoading(true)
    try {
      const response = await peptideDesignApi.listProjects({
        page,
        page_size: 12,
        status: status || undefined,
      })
      setProjectList(response.items)
      setProjectTotal(response.total)
      setProjectPage(page)
    } catch (err: any) {
      logger.error('加载项目列表失败:', err)
    } finally {
      setProjectLoading(false)
    }
  }, [])

  // 组件挂载时加载项目列表
  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    loadProjects()
  }, [loadProjects])

  // 保存当前设计为项目
  const handleSaveProject = async () => {
    if (!results) {
      addToast({ type: 'warning', title: '提示', message: '请先生成或优化肽序列' })
      return
    }

    setSavingProject(true)
    try {
      // 创建项目
      const projectResponse = await peptideDesignApi.createProject({
        project_name: `设计项目_${new Date().toLocaleDateString()}`,
        target_effects: selectedEffects.map(e => {
          // 映射中文到英文
          const map: Record<string, string> = {
            'ACE抑制': 'ACE_inhibitory',
            '抗氧化': 'antioxidant',
            'DPP-IV抑制': 'DPP_IV_inhibitory',
            '增强渗透性': 'permeability',
            '提高稳定性': 'stability',
          }
          return map[e] || e
        }),
        objective_weights: {},
      })

      const projectId = projectResponse.data.id

      // 添加候选方案
      const candidates = (results.peptides || results.optimized || []).map((p: PeptideResult | OptimizedPeptide, idx) => {
        // 使用类型守卫区分 PeptideResult 和 OptimizedPeptide
        const isPeptideResult = 'activity_scores' in p && 'composite_score' in p
        const peptide = p as PeptideResult

        return {
          sequence: p.sequence,
          objectives_scores: isPeptideResult ? (peptide.activity_scores || { composite_score: peptide.composite_score }) : { weighted_score: (p).weighted_score },
          rank: idx + 1,
          is_pareto_frontier: idx < 3, // 假设前3个是Pareto前沿
          dominated_by_count: Math.max(0, idx - 2),
        }
      })

      if (candidates.length > 0) {
        await peptideDesignApi.addCandidates(projectId, candidates)
      }

      setCurrentProjectId(projectId)
      addToast({ type: 'success', title: '保存成功', message: `项目已保存！ID: ${projectId}，包含 ${candidates.length} 个候选方案` })
      await loadProjects(1)
    } catch (err: any) {
      logger.error('保存项目失败:', err)
      addToast({ type: 'error', title: '保存失败', message: err.message || '未知错误' })
    } finally {
      setSavingProject(false)
    }
  }

  // 加载项目详情
  const handleLoadProject = async (id: number) => {
    try {
      const project = await peptideDesignApi.getProject(id)
      setSelectedProject(project.data)
      setCurrentProjectId(id)
      setMainView('design')

      // 恢复结果显示（简化版）
      if (project.data.candidates && project.data.candidates.length > 0) {
        setResults({
          peptides: project.data.candidates.map(c => ({
            sequence: c.sequence,
            molecular_weight: 0,
            logp: 0,
            tpsa: 0,
            activity_scores: c.objectives_scores,
            composite_score: Object.values(c.objectives_scores).reduce((a, b) => a + b, 0) / Object.keys(c.objectives_scores).length,
            amino_acid_count: c.sequence.length,
          })),
        })
      }
    } catch (err: any) {
      logger.error('加载项目失败:', err)
      addToast({ type: 'error', title: '加载失败', message: '请重试' })
    }
  }

  // 归档项目
  const handleArchiveProject = async (id: number) => {
    if (!confirm('确认归档此项目？归档后不可编辑。')) return

    try {
      await peptideDesignApi.archiveProject(id)
      addToast({ type: 'success', title: '归档成功', message: '项目已归档' })
      await loadProjects(projectPage, statusFilter)
      if (selectedProject?.id === id) {
        setSelectedProject(null)
      }
    } catch (err: any) {
      logger.error('归档失败:', err)
      addToast({ type: 'error', title: '归档失败', message: '请重试' })
    }
  }

  const fetchServiceStatus = useCallback(async () => {
    try {
      const status = await peptideDesignApi.getPepinventStatus()
      setServiceStatus(status)
    } catch (err: any) {
      if (err?.response?.status === 422 || err?.response?.status === 404) {
        logger.warn('[AdvancedPeptideDesign] PepInvent 服务暂不可用 (HTTP ' + (err?.response?.status || 'N/A') + ')')
        setServiceStatus({
          service_name: 'PepInvent',
          version: 'unknown',
          available: false,
          initialized: false,
          simulation_mode: true,
          device: 'unknown',
          dependencies: {
            available: false,
            missing: ['服务不可用'],
            version_info: {},
          },
          config: {},
          cache_stats: {
            cache_size: 0,
            cache_enabled: false,
          },
          models_loaded: [],
          last_error: err.message || '服务连接失败',
        } as PepinventStatusResponse)
      } else if (err?.response?.status === 401) {
        logger.warn('[AdvancedPeptideDesign] 未登录状态，跳过服务状态检查')
      } else {
        logger.error('获取服务状态失败:', err)
      }
    }
  }, [])

  React.useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    fetchServiceStatus()
  }, [fetchServiceStatus])

  const toggleEffect = (effectId: string) => {
    setSelectedEffects(prev =>
      prev.includes(effectId)
        ? prev.filter(e => e !== effectId)
        : [...prev, effectId],
    )
  }

  const handleGenerate = async () => {
    if (selectedEffects.length === 0) {
      setError('请至少选择一个目标功效')
      return
    }

    setLoading(true)
    setError(null)
    setResults(null)

    try {
      const response = await peptideDesignApi.generatePeptides(selectedEffects, { max_candidates: maxCandidates })

      if (response.success) {
        setResults({
          peptides: response.data.peptides,
          diversityMetrics: response.data.diversity_metrics,
          generationMethod: response.data.generation_method,
          processingTime: response.data.processing_time_ms,
        })
        onPeptidesGenerated?.(response.data.peptides)
      } else {
        setError('生成失败：服务返回异常状态')
      }
    } catch (err: any) {
      const status = err?.response?.status
      if (status === 405) {
        setError('接口错误 (405): API路径配置不正确，请检查前后端路由是否匹配')
        logger.error('[AdvancedPeptideDesign] HTTP 405 Method Not Allowed - 路由不匹配', { url: '/ai/peptide/generate', method: 'POST' })
      } else if (status === 422) {
        setError('参数错误 (422): 请检查输入参数是否符合要求（如目标功效、序列长度等）')
        logger.warn('[AdvancedPeptideDesign] 参数验证失败', { detail: err?.response?.data })
      } else if (status === 503) {
        logger.warn('[AdvancedPeptideDesign] PepINVERT 服务不可用，切换到模拟生成模式')
        const simulated = generateSimulatedPeptides(selectedEffects, maxCandidates)
        setResults({
          peptides: simulated as PeptideResult[],
          diversityMetrics: { tanimoto: 0.6 + Math.random() * 0.3 },
          generationMethod: 'simulation_fallback',
          processingTime: Date.now(),
        })
        onPeptidesGenerated?.(simulated as PeptideResult[])
        addToast({ type: 'info', title: '模拟模式', message: 'PepINVERT 服务不可用，已使用本地模拟生成' })
      } else if (status === 401) {
        setError('身份验证失败 (401): 请先登录后再使用肽设计功能')
        logger.warn('[AdvancedPeptideDesign] 用户未登录')
      } else if (err?.code === 'ERR_NETWORK') {
        setError('网络连接失败: 无法连接到后端服务器，请检查网络或后端服务是否启动')
      } else {
        const errorMsg = err?.response?.data?.detail || err.message || '生成过程中发生未知错误'
        setError(`生成失败: ${errorMsg}`)
        logger.error('[AdvancedPeptideDesign] 生成肽序列失败', err)
      }
    } finally {
      setLoading(false)
    }
  }

  const handleOptimize = async () => {
    const seedInput = document.getElementById('seed-sequence') as HTMLInputElement | null
    const seedSequence = seedInput?.value || ''
    if (!seedSequence || seedSequence.length < 2) {
      setError('请输入有效的种子序列（至少2个氨基酸）')
      return
    }

    const goals: Record<string, number> = {}
    OPTIMIZATION_GOALS.forEach(goal => {
      const input = document.getElementById(`goal-${goal.id}`) as HTMLInputElement | null
      if (input && input.value && parseFloat(input.value) > 0) {
        goals[goal.id] = parseFloat(input.value)
      }
    })

    const iterationsInput = document.getElementById('iterations') as HTMLInputElement | null
    const iterations = parseInt(iterationsInput?.value || '10', 10)

    setLoading(true)
    setError(null)
    setResults(null)

    try {

      if (Object.keys(goals).length === 0) {
        setError('请至少设置一个优化目标权重')
        setLoading(false)
        return
      }

      const iterationsInput = document.getElementById('iterations') as HTMLInputElement | null
      const iterations = parseInt(iterationsInput?.value || '10')

      const response = await peptideDesignApi.optimizePeptide(seedSequence, goals, iterations)

      if (response.success) {
        setResults({
          optimized: response.data.optimized_peptides,
          processingTime: response.data.processing_time_ms,
        })
      } else {
        setError('优化失败：服务返回异常状态')
      }
    } catch (err: any) {
      const status = err?.response?.status
      if (status === 405) {
        setError('接口错误 (405): API路径配置不正确，请检查前后端路由是否匹配')
        logger.error('[AdvancedPeptideDesign] HTTP 405 Method Not Allowed', { url: '/ai/peptide/optimize', method: 'POST' })
      } else if (status === 422) {
        setError('参数错误 (422): 种子序列格式错误或优化目标权重设置不当')
        logger.warn('[AdvancedPeptideDesign] 参数验证失败', { detail: err?.response?.data })
      } else if (status === 503) {
        logger.warn('[AdvancedPeptideDesign] 优化服务不可用，切换到模拟优化模式')
        const seedSeq = seedSequence
        const simOptimized: OptimizedPeptide[] = Array.from({ length: 3 }, (_, i) => ({
          sequence: randomMutate(seedSeq, 1 + i),
          scores: Object.fromEntries(Object.keys(goals).map((k, idx) => [k, Math.min(98, goals[k] * 1.2 + idx * 5)])),
          weighted_score: 0.7 + Math.random() * 0.25,
          improvement_over_seed: 0.05 + Math.random() * 0.15,
          iteration_improved: iterations,
        }))
        setResults({ optimized: simOptimized, processingTime: Date.now() })
        addToast({ type: 'info', title: '模拟模式', message: 'RL优化引擎不可用，已使用本地模拟优化' })
      } else if (err?.code === 'ERR_NETWORK') {
        setError('网络连接失败: 无法连接到后端服务器')
      } else {
        const errorMsg = err?.response?.data?.detail || err.message || '优化过程中发生未知错误'
        setError(`优化失败: ${errorMsg}`)
        logger.error('[AdvancedPeptideDesign] RL优化失败', err)
      }
    } finally {
      setLoading(false)
    }
  }

  const handleSample = async () => {
    const sampleSizeInput = document.getElementById('sample-size') as HTMLInputElement | null
    const sampleSize = parseInt(sampleSizeInput?.value || '20')
    const temperatureInput = document.getElementById('temperature') as HTMLInputElement | null
    const temperature = temperatureInput?.value ? parseFloat(temperatureInput.value) : undefined

    setLoading(true)
    setError(null)
    setResults(null)

    try {
      const response = await peptideDesignApi.sampleDiversePeptides(
        [],
        sampleSize,
        temperature,
      )

      if (response.success) {
        setResults({
          peptides: response.data.peptides.map((p: { sequence: string; molecular_weight: number; smiles?: string; properties?: Record<string, unknown>; amino_acid_count: number }) => ({
            sequence: p.sequence,
            molecular_weight: p.molecular_weight,
            logp: (p.properties?.logp as number) || 0,
            tpsa: (p.properties?.tpsa as number) || 0,
            activity_scores: {},
            composite_score: 0,
            amino_acid_count: p.amino_acid_count,
            properties: p.properties,
          })),
          diversityMetrics: {
            diversity_score: response.data.diversity_metrics.diversity_score,
            unique_count: response.data.diversity_metrics.unique_count,
            average_similarity: response.data.diversity_metrics.average_similarity,
          },
          processingTime: response.data.processing_time_ms,
        })
      }
    } catch (err: any) {
      const status = err?.response?.status
      if (status === 405) {
        setError('接口错误 (405): API路径配置不正确，请检查前后端路由是否匹配')
        logger.error('[AdvancedPeptideDesign] HTTP 405 Method Not Allowed', { url: '/ai/peptide/sample', method: 'POST' })
      } else if (status === 422) {
        setError('参数错误 (422): 采样参数超出范围（采样数量:1-100, 温度:0.1-5.0）')
        logger.warn('[AdvancedPeptideDesign] 采样参数验证失败', { detail: err?.response?.data })
      } else if (status === 503) {
        logger.warn('[AdvancedPeptideDesign] 采样服务不可用，切换到模拟采样模式')
        const simPeptides = generateSimulatedPeptides(
          Object.keys(selectedEffects).length > 0 ? selectedEffects : ['ACE抑制'],
          sampleSize,
        )
        setResults({ peptides: simPeptides as PeptideResult[], processingTime: Date.now() })
        addToast({ type: 'info', title: '模拟模式', message: '采样服务不可用，已使用本地模拟采样' })
      } else if (err?.code === 'ERR_NETWORK') {
        setError('网络连接失败: 无法连接到后端服务器')
      } else {
        const errorMsg = err?.response?.data?.detail || err.message || '采样过程中发生未知错误'
        setError(`采样失败: ${errorMsg}`)
        logger.error('[AdvancedPeptideDesign] 探索性采样失败', err)
      }
    } finally {
      setLoading(false)
    }
